        ['$L^{O}_A$', '`LO[A]`', '$g^{O}_{AA}\\,E^{O}\\tau^{O}_A(E^{O})^{-1}$', 'left multiplication by $e_A$: $e_Ae_K=\\sum_L(L^{O}_A)_{LK}e_L$'],
