        ['$N(x)$', '`oNorm2[x]`', '$x^{\\mathsf T}g^{O}x=x_0^2+\\dots+x_7^2$', 'norm'],
        ['$\\mathrm{Re}\\,x$', '`oRe[x]`', '$x_0$', 'real part'],
        ['$x^{-1}$', '`oInv[x]`', '$\\bar x/N(x)$', 'inverse'],
        ['$[x,y,z]$', '`oAssoc[x, y, z]`', '$(xy)z-x(yz)$', 'associator'],
        ['', '`toE[x]`, `ev[A]`', '$\\sum_Ax_Ae_A$; `UnitVector[8, A+1]`', 'display; coefficient list of $e_A$'],
