        ['$\\Gamma^{(1,7)}_8$', '`Γ17[8]`', '$\\Gamma^{(1,7)}_0\\cdots\\Gamma^{(1,7)}_7=\\left(\\begin{smallmatrix}0&-1_8\\\\1_8&0\\end{smallmatrix}\\right)$', 'volume element, square $-1_{16}$'],
        ['', '`products256`', '$\\Gamma^{(1,7)}_{A_1}\\cdots\\Gamma^{(1,7)}_{A_k}$, $A_1<\\dots<A_k$', 'the 256 basis products'],
        ['$\\tau^{C}_A$, $\\bar\\tau^{C}_A$', '`τC[A]`, `τCbar[A]`', '$\\tau^{C}_0=\\bar\\tau^{C}_0=i1_8$; $\\tau^{C}_k=\\tau^{O}_k$, $\\bar\\tau^{C}_k=\\bar\\tau^{O}_k$', 'complexified 8×8 matrices'],
        ['$\\Gamma^{(7,1)}_A$', '`Γ71[A]`', '$\\left(\\begin{smallmatrix}0&\\bar\\tau^{C}_A\\\\\\tau^{C}_A&0\\end{smallmatrix}\\right)$; $\\Gamma^{(7,1)}_0=iT_0$, $\\Gamma^{(7,1)}_k=T^{O}_k$', 'COMPLEX generators: $\\lbrace\\Gamma^{(7,1)}_A,\\Gamma^{(7,1)}_B\\rbrace=2\\eta^{(7,1)}_{AB}1_{16}$'],
