        ['$S$', '`Ssim`', '$(1_{16}-i\\Gamma^{(1,7)}_0)/\\sqrt2$', 'unitary; $\\Gamma^{(7,1)}_A=S(i\\Gamma^{(1,7)}_A)S^{-1}$'],
