        ['$\\varepsilon$', '`ε2`', '$\\left(\\begin{smallmatrix}0&1\\\\-1&0\\end{smallmatrix}\\right)$', '$\\varepsilon^2=-1_2$'],
        ['$\\widehat\\Gamma^{(7,1)}_A$', '`Γ71R32[A]`', '$\\varepsilon\\otimes\\Gamma^{(1,7)}_A$', 'REAL 32×32 generators with $\\eta^{(7,1)}$'],
        ['$Q_i$, $Q_j$, $Q_k$', '`Qi`, `Qj`, `Qk`', '$\\varepsilon\\otimes1_{16}$, $\\sigma_1\\otimes\\Gamma^{(1,7)}_8$, $\\sigma_3\\otimes\\Gamma^{(1,7)}_8$', 'quaternion units commuting with all $\\widehat\\Gamma^{(7,1)}_A$'],
        ['', '`commutantBasis`, `commutantTime`', '`NullSpace` of $\\lbrace X: X\\widehat\\Gamma^{(7,1)}_A=\\widehat\\Gamma^{(7,1)}_AX\\rbrace$; its timing', 'dimension 4: $\\mathbb H$'],
        ['$\\chi^{(7,1)}$', '`χ71`', '$-i\\Gamma^{(7,1)}_8=T_8$', 'chirality matrix ($\\Gamma^{(7,1)}$ basis)'],
        ['', '`PL71`, `PR71`', '$\\tfrac12(1_{16}\\mp\\chi^{(7,1)})=P_L,P_R$', '7+1 chiral projectors'],
        ['$\\chi^{(1,7)}$', '`χ17`, `PL17`, `PR17`', '$i\\Gamma^{(1,7)}_8$; $\\tfrac12(1_{16}\\mp\\chi^{(1,7)})$', 'complex chirality and projectors (rank 8)'],
